const inviteToken=()=>new URLSearchParams(location.search).get('invite')||'';
const membership=()=>session?.memberships.find(m=>m.organization_id===organization);
const currentOrg=()=>session?.organizations.find(o=>o.id===organization);
const role=()=>reviewState?.role||(session?.isAdmin?'admin':membership()?.role_id);
const can=permission=>!permission||(!reviewing()&&session?.isAdmin)||session?.permissions.some(p=>p.role_id===role()&&p.permission_id===permission);
function notify(message){const box=document.querySelector('#toast');box.textContent=message;box.classList.add('show');setTimeout(()=>box.classList.remove('show'),5000);}
async function api(path,options={}) {
 const method=options.method||'GET';
 if(method!=='GET'||path.startsWith('auth/')){reads.clear();return request(path,options);}
 const token=await accessToken();
 try{return await reads.read((token||'anonymous')+':'+path,()=>request(path,options));}
 catch(error){if([401,403].includes(error.status)){reads.clear();if(error.status===401)session=null;}throw error;}
}
async function request(path,{method='GET',body,retry=true}={}) {
 if(reviewing()&&method!=='GET'&&!path.startsWith('auth/'))throw Error('Estás revisando un perfil. Vuelve a Surtiva para hacer cambios.');
 if(path.startsWith('auth/'))return authenticate(path.slice(5),body);
 const token=['config','health'].includes(path)?null:await accessToken();
 if(!token&&!['config','health'].includes(path)){const error=Error('Ingresa para continuar.');error.status=401;throw error;}
 const response=await fetch('/api/'+path,{method,credentials:'same-origin',cache:'no-store',signal:AbortSignal.timeout(15000),headers:{...(token?{Authorization:'Bearer '+token}:{}),...(method==='GET'?{}:{'Content-Type':'application/json'})},body:body===undefined?undefined:JSON.stringify(body)});
 if(response.status===401&&retry&&!path.startsWith('auth/')) {
  try {refreshing ||= api('auth/refresh',{method:'POST',body:{},retry:false}).finally(()=>refreshing=null);await refreshing;return request(path,{method,body,retry:false});}
  catch {session=null;organization='';cart=[];}
 }
 const result=await response.json().catch(()=>({error:'No se pudo contactar el servicio.'}));
 if(!response.ok){const error=new Error(result.error||'No se pudo completar la operación.');error.status=response.status;throw error;}return result;
}
const scoped=path=>path+(path.includes('?')?'&':'?')+'organization='+encodeURIComponent(organization);
const data=(table,extra='')=>{
 if(reviewing()){
  if(!reviewState.member)return reviewState.organization?api('data/'+table+(extra||'?')+(extra?'&':'')+'organization='+encodeURIComponent(reviewState.organization)):Promise.resolve([]);
  return api('admin/review-data?resource='+table+'&membership='+reviewState.member+extra.replace('?','&'));
 }
 return ownerMode()?api('admin/data/'+table+extra):api(scoped('data/'+table+extra));
};
async function allData(table){const result=[],size=ownerMode()?500:100;for(let start=0;;start+=size){const page=await data(table,'?offset='+start+'&limit='+size);result.push(...page);if(page.length<size)break;if(start>=100000)throw Error('Demasiados registros para esta vista.');}return result;}
function header(showRequest=true){return `<header class="public-header"><a href="#portada" aria-label="Surtiva, inicio">${brand}</a><nav aria-label="Acceso">${showRequest?'<a class="btn light" href="#solicitar">Solicitar acceso</a>':''}<a class="btn primary" href="#ingresar">Ingresar ↗</a></nav></header>`;}
function landing(){return landingMarkup(header(false));}
function authPage(register=false){return header()+`<main id="contenido" class="auth-page"><section class="auth-intro"><span class="mk-eyebrow">TU PRÓXIMO PASO</span><h1>${register?'Conectemos<br>tu negocio.':'Bienvenido<br>a tu red.'}</h1><p>${register?'Cuéntanos quién eres y cómo participas. Revisaremos tu solicitud antes de habilitar tu espacio de trabajo.':'Ingresa con tu cuenta aprobada para acceder a la información de tu organización.'}</p></section><section class="auth-form"><h2>${register?'Solicitar acceso':'Ingresar'}</h2><form id="${register?'register':'login'}">${register?'<label class="field">Nombre completo<input name="name" autocomplete="name" maxlength="100" required></label><label class="field">Organización o negocio<input name="organization" autocomplete="organization" maxlength="120" required></label><label class="field">Perfil solicitado<select name="role" required><option value="">Selecciona tu perfil</option>'+Object.entries(roles).filter(([value])=>value!=='fulfillment_partner'||(inviteToken()&&new URLSearchParams(location.search).get('profile')===value)).map(([value,label])=>`<option value="${value}" ${new URLSearchParams(location.search).get('profile')===value?'selected':''}>${label}</option>`).join('')+'</select></label>':''}<label class="field">Correo electrónico<input type="email" name="email" autocomplete="email" maxlength="254" required></label><label class="field">Contraseña<input type="password" name="password" autocomplete="${register?'new-password':'current-password'}" ${register?'minlength="12"':''} maxlength="128" required></label>${register?'<small>Usa al menos 12 caracteres. Recibirás un correo para verificar tu dirección. Tu acceso necesita aprobación.</small>':''}<div class="form-feedback" role="status" aria-live="polite">${authNotice?`<p class="form-message">${esc(authNotice)}</p>`:''}</div><button class="btn primary" type="submit">${register?'Enviar solicitud':'Ingresar'}</button><a class="secondary-link" href="#${register?'ingresar':'solicitar'}">${register?'Ya tengo una cuenta':'Solicitar una cuenta'}</a>${register?'':'<a class="secondary-link" href="#recuperar">Olvidé mi contraseña</a><a class="secondary-link" href="#confirmar-correo">Reenviar confirmación de correo</a>'}</form></section></main>`;}
function pending(){if(session?.accountStatus==='suspended')return header()+'<main id="contenido" class="pending"><span class="pill orange">Acceso suspendido</span><h1>Tu organización o membresía está suspendida.</h1><p>Contacta a la administración de Surtiva para revisar el estado de tu acceso.</p><button class="btn light" data-action="logout">Cerrar sesión</button><button class="btn primary" data-action="refresh-session">Consultar estado</button></main>';const rejected=session?.accountStatus==='rejected'||session?.request?.status==='rejected';return `<header class="public-header"><a href="#portada">${brand}</a><button class="btn light" data-action="logout">Cerrar sesión</button></header><main id="contenido" class="pending"><span class="pill orange">${rejected?'Solicitud revisada':'Acceso pendiente'}</span><h1>${rejected?'Tu solicitud no fue aprobada.':'Tu solicitud está en revisión.'}</h1><p>${rejected?'Por ahora tu cuenta no tiene acceso a una organización.':'La verificación de correo y la aprobación de Surtiva son necesarias para habilitar tu espacio.'}</p><button class="btn primary" data-action="refresh-session">Consultar estado</button></main>`;}
function shell(content,page){
 const owner=ownerMode(),review=reviewing();
 const ownerSections=[['red','Mi gestión'],['catalogo','Catálogo central'],['pedidos','Control de ventas'],['radar','Radar de clientes'],['prospeccion','Prospección'],['clientes','Clientes y comercios'],['vendedores','Equipo de ventas'],['agentes','Agentes y responsables'],['seguimiento','Seguimientos'],['cartera','Cartera'],['proveedores','Proveedores'],['inventario','Inventarios'],['organizaciones','Organizaciones'],['solicitudes','Solicitudes'],['usuarios','Usuarios'],['perfiles','Revisar perfiles']];
 const nav=owner?ownerSections:sections.filter(x=>can(x[2])).map(([id,label])=>[id,label]);
 return '<div class="shell restored-shell"><button class="menu-scrim" data-action="close-menu" aria-label="Cerrar menú" tabindex="-1"></button><aside class="sidebar" id="workspace-sidebar"><button class="menu-close" data-action="close-menu" aria-label="Cerrar menú">✕</button><a class="logo" href="#'+(session.isAdmin?'red':'inicio')+'" '+(session.isAdmin?'data-action="owner-home"':'')+'>'+brand+'</a><div class="workspace">'+(owner?'<span class="owner-badge">ADMINISTRADOR MAESTRO</span><strong>Tu centro de gestión</strong><small>Toda la red Surtiva</small>':review?'<span class="owner-badge">REVISIÓN DE PERFIL</span><strong>'+esc(roles[role()])+'</strong><small>'+esc(orgName(organization))+'</small>':'<strong>'+esc(roles[role()]||'Administración')+'</strong><small>'+esc(currentOrg()?.name)+'</small>'+(session.organizations.length>1?'<label class="scope-label" for="organization">Tu espacio</label><select id="organization" class="tenant-select">'+session.organizations.map(o=>'<option value="'+o.id+'" '+(o.id===organization?'selected':'')+'>'+esc(o.name)+'</option>').join('')+'</select>':''))+'</div><nav class="navlist workspace-nav" aria-label="Área comercial">'+nav.map(([id,label])=>'<a class="navitem '+(page===id?'active':'')+'" href="#'+id+'"><span aria-hidden="true">'+(icons[id]||'·')+'</span>'+label+'</a>').join('')+'</nav><div class="sidebarfooter">'+(session.isAdmin&&!owner?'<button class="btn light full" data-action="owner-home">← Volver a mi gestión</button>':'')+'<p class="platform-profile">'+esc(session.user.name)+'<br>'+esc(session.user.email)+'</p><button class="btn light full" data-action="logout">Cerrar sesión</button></div></aside><main class="main" id="contenido"><header class="topbar"><button class="btn light mobile-toggle" data-action="menu" aria-label="Abrir menú" aria-expanded="false" aria-controls="workspace-sidebar">☰</button><strong>'+(owner?'SURTIVA / Mi gestión':esc(orgName(organization)))+'</strong><div class="topbar-actions">'+(owner?'<a href="#perfiles" class="btn light small">Revisar perfiles</a>':'')+'<span class="pill">'+(owner?'Vista global':esc(roles[role()]||'Administrador maestro'))+'</span></div></header>'+(review?'<div class="review-banner"><strong>Revisión · '+esc(roles[role()])+'</strong><span>'+(reviewState.member?'Datos y permisos del usuario seleccionado. Solo lectura.':reviewState.organization?'Datos reales de la organización. Revisión de distribuidor en solo lectura.':'Vista sin usuario asignado: muestra el estado vacío real de este perfil.')+'</span><button class="btn light small" data-action="owner-home">Salir de revisión</button></div>':'')+'<div class="content">'+content+'</div></main></div>';
}
const title=(heading,subtitle='')=>`<h1 class="section-title">${heading}</h1>${subtitle?`<p class="scope-note">${subtitle}</p>`:''}`;
async function dashboard(){
 const keys=[['orders','orders.read'],['products','catalog.read'],['clients','customers.read'],['sellers','team.read'],['invoices','receivables.read'],['followups','followups.manage'],['commissions','commissions.read'],['local_sales','retail.manage']];
 const bundle=Object.fromEntries(await Promise.all(keys.map(async([key,permission])=>[key,can(permission)&&(!ownerMode()||key!=='local_sales')?await allData(key):[]])));
 return dashboardMarkup(bundle,{owner:ownerMode(),role:role(),name:currentOrg()?.name,orgName,readonly:reviewing()});
}
async function catalogPage(){
 catalogProducts=await allData('products');rows=catalogProducts;
 return '<div class="workspace-heading"><div><span class="mk-eyebrow">'+(ownerMode()?'TODOS TUS PROVEEDORES':'CATÁLOGO COMERCIAL')+'</span><h1>'+ (ownerMode()?'Tu catálogo, completo.':role()==='merchant'?'Compra para tu negocio.':'Tu catálogo, en un solo lugar.')+'</h1><p>Busca por nombre o referencia. Compara categorías y prepara tu siguiente pedido.</p></div>'+(!reviewing()&&can('orders.create')?'<button class="btn primary" data-action="cart">Revisar pedido ('+cart.length+')</button>':'')+'</div><div class="catalog-controls"><label class="catalog-search">Buscar producto<input id="catalog-query" type="search" placeholder="Nombre o referencia del producto" value="'+esc(catalogFilters.query)+'"></label><label>Categoría<select id="catalog-category"><option value="">Todas las categorías</option>'+[...new Set(catalogProducts.map(p=>p.category))].sort().map(c=>'<option '+(catalogFilters.category===c?'selected':'')+'>'+esc(c)+'</option>').join('')+'</select></label><label>Proveedor<select id="catalog-supplier"><option value="">Todos los proveedores</option>'+[...new Set(catalogProducts.map(p=>p.organization_id))].map(id=>'<option value="'+id+'" '+(catalogFilters.supplier===id?'selected':'')+'>'+esc(orgName(id))+'</option>').join('')+'</select></label><label>Ordenar<select id="catalog-sort"><option value="name">Nombre A–Z</option><option value="low" '+(catalogFilters.sort==='low'?'selected':'')+'>Menor precio</option><option value="high" '+(catalogFilters.sort==='high'?'selected':'')+'>Mayor precio</option></select></label></div><div id="catalog-results">'+catalogResults()+'</div>'+(!reviewing()?managementTools('catalogo'):'');
}
function catalogResults(){return catalogMarkup(catalogProducts,{...catalogFilters,orgName,owner:ownerMode(),canOrder:can('orders.create'),readonly:reviewing()});}
function refreshCatalog(){document.querySelector('#catalog-results').innerHTML=catalogResults();}
function productDialog(id){const p=catalogProducts.find(p=>p.id===id);if(!p)return;dialog(p.title,'<div class="product-detail-restored">'+(p.image&&/^assets\/productos\/[a-zA-Z0-9_.-]+$/.test(p.image)?'<img src="/'+esc(p.image)+'" alt="'+esc(p.title)+'">':'')+'<div><span class="mk-eyebrow">'+esc(orgName(p.organization_id))+'</span><h2>'+esc(p.title)+'</h2><p>'+esc(p.sku)+' · '+esc(p.category)+'</p><strong class="detail-price">'+money(p.price)+'</strong><p>Precio base. El total del pedido se calcula con la política comercial vigente.</p><dl><dt>Medidas</dt><dd>'+esc(p.dimensions||'Por confirmar')+'</dd><dt>Presentación</dt><dd>'+esc(p.pack_size||'Por confirmar')+'</dd><dt>Disponibilidad</dt><dd>'+(p.active?'Consultar inventario confirmado':'Referencia inactiva')+'</dd></dl>'+(!reviewing()&&can('orders.create')&&p.active?'<button class="btn primary" data-action="add-product" data-id="'+p.id+'">Agregar al pedido</button>':'')+(manager()?'<button class="btn light" data-action="edit-product" data-id="'+p.id+'">Editar ficha</button>':'')+'</div></div>');}

const badge=value=>`<span class="pill ${['entregado','active'].includes(value)?'green':'orange'}">${esc(states[value]||value)}</span>`;
const table=(headers,body)=>`<div class="panel tablewrap"><table class="data-table"><thead><tr>${headers.map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${body||`<tr><td colspan="${headers.length}"><div class="empty-state">Todavía no hay registros disponibles en este espacio.</div></td></tr>`}</tbody></table></div>`;
const productName=p=>`<div class="table-product">${p.image&&/^assets\/productos\/[a-zA-Z0-9_.-]+$/.test(p.image)?`<img class="table-image" src="/${esc(p.image)}" alt="" loading="lazy">`:''}<span><strong>${esc(p.title)}</strong><small>${esc(p.sku)}</small></span></div>`;
const scopeLabel=r=>ownerMode()&&r.organization_id?'<small>'+esc(orgName(r.organization_id))+'</small>':'';
function tableView(page,list){
 if(!list.length)return emptyView(page);
 if(page==='puntos')return table(['Punto','Ciudad'],list.map(r=>`<tr><td>${esc(r.name)}${scopeLabel(r)}</td><td>${esc(r.city||'—')}</td></tr>`).join(''));
 if(page==='catalogo')return table(['Producto','Categoría','Precio base',''],list.map(p=>`<tr><td>${productName(p)}</td><td>${esc(p.category)}</td><td>${money(p.price)}<small>Precio por volumen al pedir</small></td><td>${can('orders.create')&&p.active?`<button class="btn light small" data-action="add-product" data-id="${p.id}">Agregar</button>`:badge(p.active?'Habilitado':'Inactivo')}</td></tr>`).join(''));
 if(page==='inventario')return table(['Producto','Físico','Comprometido',''],list.map(p=>`<tr><td>${esc(p.productTitle||p.product_id)}</td><td>${p.quantity??'Por confirmar'}</td><td>${p.reserved}</td><td>${!reviewing()?`<button class="btn light small" data-action="edit-stock" data-id="${p.product_id}">Actualizar</button>`:''}</td></tr>`).join(''));
 if(page==='clientes')return table(['Cliente','Ciudad',''],list.map(c=>`<tr><td>${esc(role()==='merchant'?c.distributor_name||c.name:c.name)}${scopeLabel(c)}</td><td>${esc(c.city||'—')}</td><td>${!reviewing()&&can('followups.manage')&&c.seller_id?`<button class="btn light small" data-action="followup" data-id="${c.id}">Seguimiento</button>`:''}${manager()?` <button class="btn light small" data-action="assign-seller" data-id="${c.id}">Asignar vendedor</button>`:''}</td></tr>`).join(''));
 if(page==='pedidos')return table(['Pedido','Fecha','Total','Estado',''],list.map(o=>`<tr><td>${esc(o.number)}${scopeLabel(o)}${o.is_example?'<small>Ejemplo</small>':''}</td><td>${date(o.created_at)}</td><td>${money(o.total)}</td><td>${badge(o.status)}</td><td><button class="btn light small" data-action="order" data-id="${o.id}">Ver pedido</button></td></tr>`).join(''));
 if(page==='vendedores'||page==='proveedores')return table(['Nombre',page==='vendedores'?'Territorio':'Contacto'],list.map(r=>`<tr><td>${esc(r.name)}${scopeLabel(r)}</td><td>${esc(r.territory||r.contact||'—')}</td></tr>`).join(''));
 if(page==='comisiones')return table(['Pedido','Comisión','Estado'],list.map(r=>`<tr><td>${esc(r.orderNumber||r.order_id)}</td><td>${money(r.amount)}</td><td>${esc(r.status)}</td></tr>`).join(''));
 if(page==='seguimiento')return table(['Cliente','Nota','Próximo contacto'],list.map(r=>`<tr><td>${esc(r.customerName||r.customer_id)}</td><td>${esc(r.note)}</td><td>${date(r.next_date)}</td></tr>`).join(''));
 if(page==='cartera')return table(['Documento','Vencimiento','Total','Saldo'],list.map(r=>`<tr><td>${esc(r.number)}</td><td>${date(r.due_date)}</td><td>${money(r.total)}</td><td>${money(r.total-r.paid)}</td></tr>`).join(''));
 if(page==='miinventario')return table(['Producto','Unidades','Precio local'],list.map(r=>`<tr><td>${esc(r.productTitle||r.product_id)}</td><td>${r.quantity}</td><td>${money(r.price)}</td></tr>`).join(''));
 if(page==='ventas')return table(['Fecha','Venta','Total'],list.map(r=>`<tr><td>${date(r.created_at)}</td><td>${esc(r.id.slice(0,8))}</td><td>${money(r.total)}</td></tr>`).join(''));
 if(page==='cumplimiento')return table(['Pedido','Stock comprometido','Despacho','Estado de pago','Conciliación'],list.map(r=>`<tr><td>${esc(r.orderNumber||r.order_id)}</td><td>${esc(r.committed_stock.map(l=>`${l.sku||l.title||l.productId}: ${l.quantity}`).join(', '))}</td><td>${esc(r.dispatch_reference||'Pendiente')}</td><td>${esc(r.payment_status)}</td><td>${esc(r.reconciliation_status)}</td></tr>`).join(''));
 if(page==='invitaciones')return table(['Nombre','Correo','Perfil','Estado','Vence'],list.map(i=>`<tr><td>${esc(i.name)}</td><td>${esc(i.email)}</td><td>${esc(roles[i.role_id])}</td><td>${badge(i.status==='pending'&&new Date(i.expires_at)<new Date()?'Vencida':i.status)}</td><td>${date(i.expires_at)}</td></tr>`).join(''));
 if(page==='usuarios')return table(['Usuario','Rol','Estado',''],list.map(r=>`<tr><td>${esc(r.profiles?.name||r.user_id)}</td><td>${esc(roles[r.role_id]||'Administrador maestro de Surtiva')}</td><td>${badge(r.status)}</td><td><button class="btn light small" data-action="membership" data-id="${r.id}">${r.status==='active'?'Suspender':'Activar'}</button></td></tr>`).join(''));
 return '';
}
async function enrich(page,list){
 if(['inventario','miinventario'].includes(page)){const products=await allData('products');return list.map(r=>({...r,productTitle:products.find(p=>p.id===r.product_id)?.title}));}
 if(['comisiones','cumplimiento'].includes(page)){const orders=await allData('orders');return list.map(r=>({...r,orderNumber:orders.find(o=>o.id===r.order_id)?.number}));}
 if(page==='seguimiento'){const customers=await allData('clients');return list.map(r=>({...r,customerName:customers.find(c=>c.id===r.customer_id)?.name}));}
 return list;
}
async function render(){
 const version=++renderVersion,page=route();modal.close();setMenu(false);
 if(page==='confirmar-correo'){app.innerHTML=confirmationPage();checkConfiguration(version);return;}
 if(page==='activar-administrador'){app.innerHTML=ownerActivationPage();checkConfiguration(version);return;}
 if(page==='verificar-recuperacion'){app.innerHTML=recoveryCodePage();checkConfiguration(version);return;}
 if(['recuperar','nueva-clave'].includes(page)){app.innerHTML=recoveryPage(page==='nueva-clave');checkConfiguration(version);return;}
 if(page==='portada'){app.innerHTML=landing();return;}
 if(['ingresar','acceso','solicitar'].includes(page)){app.innerHTML=authPage(page==='solicitar');checkConfiguration(version);return;}
 if(session){
  const area=app.querySelector('.content');
  const loading='<div class="route-loading" role="status"><span></span>Cargando sección…</div>';
  if(area){area.innerHTML=loading;app.querySelectorAll('.navitem').forEach(a=>a.classList.toggle('active',a.hash==='#'+page));}
  else app.innerHTML=shell(loading,page);
 }else app.innerHTML='<div class="boot"><b>surtiva<span>✳</span></b><p>Abriendo tu espacio…</p></div>';
 try {
  session=await api('session');if(version!==renderVersion)return;
  if(!session.isAdmin&&!session.memberships.length){app.innerHTML=pending();return;}
  if(!session.isAdmin)session.organizations=session.organizations.filter(o=>o.status==='active'&&session.memberships.some(m=>m.organization_id===o.id));
  if(!ownerMode()&&!reviewing()&&!session.organizations.some(o=>o.id===organization))organization=session.organizations.find(o=>o.kind!=='plataforma')?.id||session.organizations[0]?.id||'';
  if(page==='pendiente'){location.hash=session.isAdmin?'red':'inicio';return;}
  let content='';
  if(page==='red'&&session.isAdmin){workspaceMode=false;reviewState=null;content=await dashboard();}
  else if(page==='organizaciones'&&session.isAdmin)content=network();
  else if(page==='perfiles'&&session.isAdmin)content=await profileReviewPage();
  else if(page==='radar'&&ownerMode()){const [clients,orders,followups]=await Promise.all(['clients','orders','followups'].map(allData));radarClients=clients;content=scanMarkup(clients,orders,followups,orgName);}
  else if(page==='prospeccion'&&ownerMode()){[crmProspects,crmAgents]=await Promise.all(['prospects','commercial_agents'].map(allData));content=crmMarkup(crmProspects,crmAgents);}
  else if(page==='agentes'&&ownerMode())content=await agentsPage();
  else if(page==='catalogo'&&can('catalog.read'))content=await catalogPage();
  else if(page==='solicitudes'&&session.isAdmin){const requests=await api('admin/requests');if(version!==renderVersion)return;rows=requests;content=title('Solicitudes de acceso.','La aprobación define organización, rol y asignaciones. El correo debe estar verificado.')+`<div class="panel">${rows.map(r=>`<article class="access-row"><div><h3>${esc(r.profiles?.name||'Solicitante')}</h3><p>${esc(r.organization_name)} · ${esc(roles[r.requested_role])}</p>${badge(r.status)}</div>${r.status==='pending'?`<button class="btn primary small" data-action="review" data-id="${r.id}">Revisar solicitud</button>`:''}</article>`).join('')||'<div class="empty-state">No hay solicitudes.</div>'}</div>`;}
  else if(page==='inicio')content=(organization||reviewing()||ownerMode())?await dashboard():title('Tu red está lista para crecer.','Revisa las solicitudes para incorporar organizaciones.');
  else if((page==='usuarios'&&session.isAdmin)||sections.some(s=>s[0]===page&&can(s[2]))){
   if(!organization&&!ownerMode()&&!reviewing())throw Error('Primero selecciona o crea una organización.');
   const raw=await data(page==='usuarios'?'memberships':tableFor[page],'?offset='+offset);const enriched=await enrich(page,raw);if(version!==renderVersion)return;rows=enriched;
   content=title(page==='usuarios'?'Usuarios y permisos.':sections.find(s=>s[0]===page)?.[1]+'.',page==='cumplimiento'?'Solo pedidos y movimientos de tus puntos asignados. Los pagos y conciliaciones son registros; no se procesan pagos.':page==='comisiones'?'Proyecciones según la política de tu organización. Sin procesamiento de pagos.':ownerMode()?'Datos de toda la red · cada registro conserva su organización.':'Información de '+esc(currentOrg()?.name)+'.')+`<div class="toolbar"><label>Buscar en esta página <input id="search" type="search" placeholder="Escribe para filtrar"></label>${page==='catalogo'&&can('orders.create')?`<button class="btn primary" data-action="cart">Revisar pedido (${cart.length})</button>`:''}</div><div id="data-list">${tableView(page,rows)}</div><div class="toolbar"><span class="data-summary">${rows.length} registros · Página ${offset/100+1}</span><div><button class="btn light small" data-action="previous" ${offset===0?'disabled':''}>Anterior</button> <button class="btn light small" data-action="next" ${raw.length<100?'disabled':''}>Siguiente</button></div></div>`;
   content+=managementTools(page);
  } else content=title('Sección no disponible.','Tu cuenta no tiene permiso para acceder a esta sección.')+'<a class="btn primary" href="#inicio">Volver a mi espacio</a>';
  if(version===renderVersion)app.innerHTML=shell(content,page);
 } catch(error){if(version!==renderVersion)return;if(error.status===401){session=null;app.innerHTML=authPage(false);checkConfiguration(version);}else {const message='<div class="empty-state"><h2>No pudimos cargar esta sección.</h2><p>'+esc(error.name==='TimeoutError'?'La conexión tardó demasiado. Puedes seguir navegando o volver a intentar.':error.message)+'</p><button class="btn primary" data-action="refresh-session">Reintentar</button></div>';app.innerHTML=session?shell(message,page):header()+message;}}
}
async function checkConfiguration(version){try{const health=await api('health');if(version!==renderVersion||health.configured)return;const form=app.querySelector('.auth-form form');if(form){form.querySelector('.form-feedback').innerHTML='<p class="form-message">Estamos habilitando el acceso a Surtiva. El registro y el ingreso todavía no están disponibles.</p>';form.querySelector('button[type="submit"]').disabled=true;}}catch{/* The server still fails closed if configuration cannot be checked. */}}
function dialog(titleText,body){modal.innerHTML=`<div class="dialoghead"><h2>${esc(titleText)}</h2><button class="btn light small" data-action="close" aria-label="Cerrar">✕</button></div><div class="dialogbody">${body}<div class="form-feedback" role="status" aria-live="polite"></div></div>`;modal.showModal();}
function managementTools(page){
 if(reviewing())return '';
 if(!rows.length)return '';
 const invitations={vendedores:['seller','Invitar vendedor'],clientes:['merchant','Invitar comercio'],puntos:['fulfillment_partner','Invitar aliado'],invitaciones:['seller','Crear invitación']};
 const entities={catalogo:['product','Agregar producto'],proveedores:['supplier','Agregar proveedor']};
 return '<div class="toolbar">'+(manager()&&(ownerMode()||currentOrg()?.kind==='distribuidor')&&invitations[page]&&(page!=='puntos'||session.isAdmin)?'<button class="btn primary" data-action="invite" data-role="'+invitations[page][0]+'">'+invitations[page][1]+'</button>':'')+(manager()&&entities[page]?'<button class="btn primary" data-action="create-entity" data-kind="'+entities[page][0]+'">'+entities[page][1]+'</button>':'')+(manager()&&!ownerMode()&&page==='catalogo'?'<button class="btn light" data-action="catalog-access">Administrar catálogo habilitado</button>':'')+(manager()&&page==='pedidos'?'<button class="btn light" data-action="assign-point">Asignar punto de cumplimiento</button>':'')+(page==='miinventario'?'<button class="btn light" data-action="retail-edit">Editar inventario local</button><button class="btn primary" data-action="retail-sale">Registrar venta local</button>':'')+'</div>';
}
function emptyView(page){
 const copy={vendedores:['Aún no tienes vendedores','Invita a una persona a tu equipo. Podrá ingresar después de verificar su correo y recibir aprobación.','invite','seller','Invitar vendedor'],clientes:['Aún no tienes comercios','Vincula una organización comercial mediante una invitación y aprobación.','invite','merchant','Agregar primer comercio'],puntos:['Aún no tienes aliados de cumplimiento','Invita a un aliado para coordinar los pedidos que le asignes.','invite','fulfillment_partner','Invitar aliado'],proveedores:['Aún no tienes proveedores','Registra el primer proveedor de tu organización.','create-entity','supplier','Agregar proveedor'],catalogo:['Tu catálogo está vacío',manager()?'Agrega productos para comenzar a recibir pedidos.':'Tu distribuidor todavía no ha habilitado productos para tu cuenta.','create-entity','product','Agregar producto'],pedidos:['Aún no hay pedidos',role()==='fulfillment_partner'?'Aquí aparecerán únicamente los pedidos que te asignen.':'Los pedidos registrados aparecerán aquí con su estado y seguimiento.'],inventario:['Aún no hay inventario','Agrega productos y confirma sus existencias antes de preparar pedidos.'],miinventario:['Tu inventario local está vacío','Las compras entregadas se incorporarán aquí. Después podrás registrar tus ventas locales.'],ventas:['Aún no hay ventas locales','Registra una venta desde tu inventario local cuando tengas existencias.'],cartera:['No hay facturas pendientes','Aquí consultarás los documentos de tus pedidos entregados.'],comisiones:['Aún no hay comisiones','Se generarán con tus pedidos según la política de tu organización.'],seguimiento:['Aún no hay seguimientos','Abre uno de tus clientes para registrar una nota y el próximo contacto.'],cumplimiento:['No hay despachos asignados','Los compromisos de stock y despachos aparecerán al asignarte pedidos.'],invitaciones:['Aún no has enviado invitaciones','Crea un enlace para compartir con la persona que quieres incorporar.','invite','seller','Crear invitación'],usuarios:['Esta organización aún no tiene usuarios','Aprueba una solicitud para asignar la primera membresía.']};
 const [heading,detail,action,value,label]=copy[page]||['Sin resultados','No encontramos registros con este filtro.'];
 const button=manager()&&(ownerMode()||currentOrg()?.kind==='distribuidor')&&action&&(value!=='fulfillment_partner'||session.isAdmin)?'<button class="btn primary" data-action="'+action+'" data-'+(action==='invite'?'role':'kind')+'="'+value+'">'+label+'</button>':'';
 const link=page==='pedidos'&&can('orders.create')?'<a class="btn primary" href="#catalogo">Explorar catálogo</a>':page==='ventas'?'<a class="btn primary" href="#miinventario">Ver inventario local</a>':page==='seguimiento'?'<a class="btn primary" href="#clientes">Ver clientes</a>':'';
 return '<section class="empty-state panel"><h2>'+heading+'</h2><p>'+detail+'</p>'+button+link+'</section>';
}
function recoveryCodePage(){return header()+`<main id="contenido" class="auth-page"><section class="auth-intro"><h1>Verifica tu recuperación.</h1><p>Introduce el código del correo más reciente. Después podrás elegir una nueva contraseña.</p></section><section class="auth-form"><h2>Código de recuperación</h2><form id="verify-recovery"><label class="field">Correo electrónico<input name="email" type="email" autocomplete="email" maxlength="254" value="${esc(recoveryEmail)}" required></label><label class="field">Código del correo<input name="token" type="text" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6,10}" minlength="6" maxlength="10" required></label><div class="form-feedback" role="status" aria-live="polite">${authNotice?`<p class="form-message">${esc(authNotice)}</p>`:''}</div><button class="btn primary" type="submit">Verificar código</button><a class="secondary-link" href="#recuperar">Solicitar otro correo</a><a class="secondary-link" href="#ingresar">Volver al ingreso</a></form></section></main>`;}
function ownerActivationPage(){return header()+'<main id="contenido" class="auth-page"><section class="auth-intro"><span class="mk-eyebrow">PROPIETARIO DE SURTIVA</span><h1>Administrador maestro.</h1><p>Administra toda la red: organizaciones, usuarios, permisos y operaciones. Tu cuenta pertenece a Surtiva y conserva acceso global.</p></section><section class="auth-form"><h2>Activar mi cuenta maestra</h2><form id="register-owner"><label class="field">Nombre completo<input name="name" autocomplete="name" maxlength="100" required></label><label class="field">Correo del propietario<input name="email" type="email" autocomplete="email" maxlength="254" required></label><label class="field">Contraseña<input name="password" type="password" autocomplete="new-password" minlength="12" maxlength="128" required></label><small>Usa al menos 12 caracteres. El acceso maestro se activa al verificar el correo autorizado del propietario.</small><div class="form-feedback" role="status" aria-live="polite"></div><button class="btn primary" type="submit">Activar administración maestra</button><a class="secondary-link" href="#ingresar">Ya tengo una cuenta</a></form></section></main>';}
function confirmationPage(){return header()+'<main id="contenido" class="auth-page"><section class="auth-intro"><h1>Verifica tu correo.</h1><p>Solicita un nuevo enlace para la cuenta que ya registraste. Usa el correo más reciente y ábrelo en este mismo navegador.</p></section><section class="auth-form"><h2>Reenviar confirmación</h2><form id="resend"><label class="field">Correo electrónico<input name="email" type="email" autocomplete="email" maxlength="254" required></label><div class="form-feedback" role="status" aria-live="polite">'+(authNotice?'<p class="form-message">'+esc(authNotice)+'</p>':'')+'</div><button class="btn primary" type="submit">Enviar nuevo enlace</button><a href="#ingresar">Ya verifiqué mi correo: ingresar</a></form></section></main>';}
function recoveryPage(change=false){return header()+'<main id="contenido" class="auth-page"><section class="auth-intro"><h1>'+ (change?'Elige tu nueva contraseña.':'Recupera tu acceso.')+'</h1><p>Tu organización y tus permisos se conservan.</p></section><section class="auth-form"><form id="'+(change?'password':'recover')+'">'+(change?'<label class="field">Nueva contraseña<input name="password" type="password" minlength="12" maxlength="128" autocomplete="new-password" required></label>':'<label class="field">Correo electrónico<input name="email" type="email" autocomplete="email" required></label>')+'<div class="form-feedback" role="status">'+(authNotice?'<p class="form-message">'+esc(authNotice)+'</p>':'')+'</div><button class="btn primary" type="submit">'+(change?'Guardar contraseña':'Enviar correo de recuperación')+'</button><a href="#ingresar">Volver al ingreso</a></form></section></main>';}
function invitationDialog(selected){dialog('Invitar a tu red','<form id="invitation">'+organizationField()+'<label>Nombre de la persona o negocio<input name="name" maxlength="100" required></label><label>Correo de quien recibirá acceso<input name="email" type="email" maxlength="254" required></label><label>Perfil<select name="role">'+Object.entries(roles).filter(([r])=>r!=='distributor_admin'&&(r!=='fulfillment_partner'||session.isAdmin)).map(([r,label])=>'<option value="'+r+'" '+(r===selected?'selected':'')+'>'+label+'</option>').join('')+'</select></label><p class="scope-note">Obtendrás un enlace válido durante 7 días para compartir. El acceso requiere correo verificado y aprobación de Surtiva.</p><button class="btn primary" type="submit">Crear enlace de invitación</button></form>');}
function network(){return title('Organizaciones de la red.','Administración de empresas y estados; tu gestión global permanece en Mi gestión.')+table(['Organización','Tipo','Estado','Plan',''],session.organizations.map(o=>'<tr><td>'+esc(o.name)+(o.is_test?'<small>Organización de prueba</small>':'')+'</td><td>'+esc(o.kind)+'</td><td>'+badge(o.status)+'</td><td>'+esc(o.plan_code)+'</td><td><button class="btn light small" data-action="select-org" data-id="'+o.id+'">Gestionar organización</button> '+(o.kind!=='plataforma'?'<button class="btn light small" data-action="org-status" data-id="'+o.id+'">Cambiar estado</button>':'')+'</td></tr>').join(''));}
function organizationField(){return ownerMode()?'<label>Proveedor responsable<select name="organizationContext" required><option value="">Selecciona para esta operación</option>'+session.organizations.filter(o=>o.kind==='distribuidor'&&o.status==='active'&&!o.is_test).map(o=>'<option value="'+o.id+'">'+esc(o.name)+'</option>').join('')+'</select></label>':'';}
async function profileReviewPage(){workspaceMode=false;reviewState=null;return title('Revisar perfiles.','Tu misma cuenta maestra. Revisa cada experiencia sin compartir contraseñas ni cambiar tus permisos.')+'<div class="profile-review-grid">'+Object.entries(roles).map(([value,label])=>'<article class="panel work-panel"><span class="mk-eyebrow">ESPACIO DE TRABAJO</span><h2>'+label+'</h2><p>'+({distributor_admin:'Catálogo, inventario, pedidos y equipo de su organización.',seller:'Clientes asignados, catálogo habilitado y seguimiento.',merchant:'Compras, cartera, inventario y ventas locales.',fulfillment_partner:'Pedidos asignados, despacho y conciliación.'}[value])+'</p><button class="btn primary" data-action="review-profile" data-role="'+value+'">Revisar '+label.toLowerCase()+' ↗</button></article>').join('')+'</div>';}
async function beginReview(chosen){
 const members=await allData('memberships');
 const matches=members.filter(m=>m.role_id===chosen&&m.status==='active'&&session.organizations.some(o=>o.id===m.organization_id&&o.status==='active'));
 dialog('Revisar '+roles[chosen],'<form id="review-profile-form"><input type="hidden" name="role" value="'+chosen+'"><label>Cuenta a revisar<select name="member"><option value="">Vista de perfil sin cuenta asignada</option>'+(chosen==='distributor_admin'?session.organizations.filter(o=>o.kind==='distribuidor'&&o.status==='active'&&!o.is_test).map(o=>'<option value="org:'+o.id+'" data-org="'+o.id+'" selected>'+esc(o.name)+' · vista de organización</option>').join(''):'')+matches.map(m=>'<option value="'+m.id+'" data-org="'+m.organization_id+'">'+esc(orgName(m.organization_id))+' · '+esc(m.profiles?.name||m.user_id.slice(0,8))+'</option>').join('')+'</select></label><p class="scope-note">'+(matches.length?'Las cuentas activas muestran sus datos reales bajo sus políticas de acceso.':chosen==='distributor_admin'?'Puedes revisar el catálogo y la operación real de un distribuidor, aunque aún no tenga un usuario activo.':'Todavía no hay usuarios activos con este perfil. Puedes revisar su estructura y estados vacíos; los datos aparecerán cuando apruebes cuentas y asignaciones.')+'</p><button class="btn primary">Abrir perfil</button></form>');
}
